import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ fullName: '', email: '', password: '' });
  const [error, setError] = useState('');

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      // Calling backend to register
      await axios.post('http://localhost:5000/api/auth/register', formData);
      navigate('/login');
    } catch (err) {
      setError(err.response?.data?.error || 'Registration failed');
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: 'var(--light)' }}>
      <div className="bg-white p-5 rounded-4 shadow-sm" style={{ width: '100%', maxWidth: '450px', border: '1px solid var(--border)' }}>
        <div className="text-center mb-4">
          <Link to="/" style={{ textDecoration: 'none', color: 'var(--dark)' }}>
            <h2 className="fw-bold"><i className="fa-solid fa-bolt text-primary"></i> VRX</h2>
          </Link>
          <h3 className="mt-4 fw-bold">Create Account</h3>
          <p className="text-muted">Start riding smarter today.</p>
        </div>

        {error && <div className="alert alert-danger py-2">{error}</div>}

        <form onSubmit={handleRegister}>
          <div className="mb-3">
            <label className="form-label fw-bold">Full Name</label>
            <input type="text" name="fullName" required className="form-control p-3 bg-light" placeholder="John Doe" onChange={handleChange} />
          </div>
          <div className="mb-3">
            <label className="form-label fw-bold">Email Address</label>
            <input type="email" name="email" required className="form-control p-3 bg-light" placeholder="student@university.edu" onChange={handleChange} />
          </div>
          <div className="mb-4">
            <label className="form-label fw-bold">Password</label>
            <input type="password" name="password" required className="form-control p-3 bg-light" placeholder="Create a strong password" onChange={handleChange} />
          </div>
          <button type="submit" className="btn btn-primary-custom w-100 py-3">Sign Up</button>
        </form>

        <div className="text-center mt-4 text-muted">
          Already have an account? <Link to="/login" className="fw-bold text-primary">Log in</Link>
        </div>
      </div>
    </div>
  );
};

export default Register;
